def main():
    OUT.mkdir(parents=True, exist_ok=True)
    paths = []
    for name, content in STUBS.items():
        path = OUT / "fake" / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        paths.append(str(path))
    test = OUT / "PanelSelfTest.java"
    test.write_text(TEST, encoding="utf-8")
    jdk = Path(os.environ.get("JAVA_HOME", "")) / "bin"
    javac = str(jdk / "javac.exe") if (jdk / "javac.exe").exists() else "javac"
    java = str(jdk / "java.exe") if (jdk / "java.exe").exists() else "java"
    sources = [str(SOURCE / name) for name in ("TextOverlay.java", "Viewport.java", "DisplayPrefs.java")]
    subprocess.run([javac, "-encoding", "UTF-8", "-d", str(OUT / "classes"), *paths, *sources, str(test)], check=True)
    result = subprocess.run([java, "-cp", str(OUT / "classes"), "org.mahoyo.port.PanelSelfTest"], check=True, capture_output=True, text=True)
    (OUT / "result.txt").write_text(result.stdout, encoding="utf-8")
    print(result.stdout.strip())


if __name__ == "__main__":
    main()
